#!/bin/bash
# Precondition: the question's situation on the lab's node. K3s runs with the lab's binary; its containerd's root is <data-dir>/agent/containerd on the lab's own file system (the data-dir is the one in the unit's
# config.yaml); the generated config.toml ("File generated by k3s") has no root; `k3s ctr images import` has no option for a directory. The external disk is the lab's loop mount, empty. The seed Pod
# runs (the uid of setup) from the seed image (the digest of setup). Control: an image imported now has its layer blob in the old root, on the lab's file system, and nothing is on the disk.
CASE_ID="bench58642878"
LIB="/var/lib/$CASE_ID"
DISK="/mnt/$CASE_ID-disk"
STATE_DIR="/tmp/$CASE_ID/.bench"
fail() { echo "[precondition] FAIL: $*"; exit 1; }

[ "$(sudo cat "$STATE_DIR/ready" 2>/dev/null | wc -c)" -gt 0 ] || fail "setup.sh has not run"
sudo sh -c "cd / && sha256sum -c --quiet '$STATE_DIR/lab.sha' && sha256sum -c --quiet '$STATE_DIR/pause.sha' && sha256sum -c --quiet '$STATE_DIR/config.initial.sha'" >/dev/null 2>&1 || fail "a program of the lab, the sandbox image or the unit's configuration changed since setup"
sudo "$LIB/bin/k3sctl" status >/dev/null 2>&1 || fail "the node does not run"
res=$(sudo python3 - "$LIB" "$DISK" "$STATE_DIR" 2>&1 <<'PY'
import json, os, re, subprocess, sys

lib, disk, state = sys.argv[1:4]
truth = json.load(open(state + "/truth.json"))
k3s = lib + "/bin/k3s"


def fail(msg):
    print("FAIL: " + msg)
    sys.exit(1)


def sh(*a, inp=None):
    r = subprocess.run(a, capture_output=True, text=True, timeout=120)
    return r.returncode, (r.stdout + r.stderr).strip()


def containerd_meta():
    found = []
    for p in subprocess.run(["pgrep", "-x", "containerd"], capture_output=True, text=True).stdout.split():
        try:
            if "/k3s/data/" not in os.readlink("/proc/%s/exe" % p):    # k3s' own containerd runs the tools k3s unpacked
                continue
            for fd in os.listdir("/proc/%s/fd" % p):
                t = os.readlink("/proc/%s/fd/%s" % (p, fd))
                if t.endswith("/io.containerd.metadata.v1.bolt/meta.db"):
                    found.append((p, t))
        except OSError:
            pass
    return found


c = containerd_meta()
if len(c) != 1:
    fail("expected one containerd of a k3s, found %s" % c)
meta = c[0][1]
root = os.path.dirname(os.path.dirname(meta))
if os.path.realpath(root) != truth["orig_root"] or os.stat(root).st_dev != truth["lab_dev"]:
    fail("containerd's root is %s (device %s), not the data-dir's %s on the lab's file system" % (root, os.stat(root).st_dev, truth["orig_root"]))
data = os.path.dirname(os.path.dirname(root))
cfg = open(data + "/agent/etc/containerd/config.toml").read()
if "File generated by k3s" not in cfg or re.search(r"^\s*root\s*=", cfg, re.M):
    fail("the generated config.toml is not as k3s makes it (header missing or a root in it)")
rc, helptxt = sh(k3s, "ctr", "images", "import", "--help")
flags = sorted(set(re.findall(r"--([a-z][a-z-]*)", helptxt.split("OPTIONS:")[-1])))
if rc != 0 or not flags or [f for f in flags if re.search(r"dir|root|path|data|store|location", f)]:
    fail("`k3s ctr images import` has an option for a place (or no help): %s" % flags)

if not os.path.ismount(disk) or os.stat(disk).st_dev != truth["disk_dev"] or truth["disk_dev"] == truth["lab_dev"]:
    fail("the disk is not mounted as setup made it")
rc, src = sh("findmnt", "-n", "-o", "SOURCE", disk)
rc, back = sh("losetup", "-nO", "BACK-FILE", src)
if os.path.realpath(back) != os.path.realpath(truth["disk_img"]):
    fail("the disk's loop device does not belong to the lab's file %s: %s" % (truth["disk_img"], back))
if sorted(os.listdir(disk)) != ["lost+found"]:
    fail("the disk is not empty: %s" % os.listdir(disk))

rc, out = sh(k3s, "kubectl", "get", "pod", "b58642878-seed", "-o", "jsonpath={.metadata.uid} {.status.phase}")
if out != truth["seed_pod_uid"] + " Running":
    fail("the seed Pod is not the one of setup or does not run: %s" % out)
rc, out = sh(k3s, "ctr", "images", "ls")
if "bench.local/seed:1" not in out or truth["seed_manifest"] not in out:
    fail("the seed image of setup is not in containerd: %s" % out[:200])
rc, out = sh(k3s, "kubectl", "logs", "b58642878-seed")
if out != "salt=" + truth["seed_salt"]:
    fail("the seed Pod does not print the seed salt: %r" % out)

# control: what an import does now
salt = os.urandom(8).hex()
tar = state + "/probe.tar"
rc, man = sh("python3", state + "/mkimg.py", tar, "bench.local/probe:1", "app", state + "/app", salt)
rc, o = sh(k3s, "ctr", "images", "import", tar)
if rc != 0:
    fail("the control import failed: " + o[-200:])
rc, mj = sh(k3s, "ctr", "content", "get", man)
layer = json.loads(mj)["layers"][0]["digest"].split(":")[1]
blob = root + "/io.containerd.content.v1.content/blobs/sha256/" + layer
if not os.path.exists(blob) or os.stat(blob).st_dev != truth["lab_dev"]:
    fail("the control import's layer blob is not in the old root on the lab's file system")
sh(k3s, "ctr", "images", "rm", "bench.local/probe:1")
os.remove(tar)
if sorted(os.listdir(disk)) != ["lost+found"]:
    fail("something is on the disk after the control import")
print("k3s (the lab's binary) has its containerd at %s on the lab's file system; the generated config.toml has no root; `k3s ctr images import` has no place option (%s); an image imported now has its blobs in that root and the empty external disk gets nothing; the seed Pod and image are as setup made them" % (root, ", ".join(flags)))
PY
) || fail "$res"
echo "[precondition] PASS: $res"
